package com.dentalclinic.patientcare.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.*;
@Entity @Table(name="patient_care_history") public class CareHistoryEntry { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull private Long patientId; @NotNull private LocalDate visitDate; @NotBlank @Size(max=120) private String treatment; @Size(max=1000) private String notes; @Size(max=120) private String dentistName;
public Long getId(){return id;}public void setId(Long v){id=v;}public Long getPatientId(){return patientId;}public void setPatientId(Long v){patientId=v;}public LocalDate getVisitDate(){return visitDate;}public void setVisitDate(LocalDate v){visitDate=v;}public String getTreatment(){return treatment;}public void setTreatment(String v){treatment=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public String getDentistName(){return dentistName;}public void setDentistName(String v){dentistName=v;}}
// LEADER MERGE: If Treatment module already has a treatment/history entity, replace this table with a read-only DTO/API integration to avoid duplicate clinical data.
